import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:just_audio/just_audio.dart';

/// OLFA's own in-app sounds (generated by tools/make_sounds.py):
/// a short two-note tone for messages, a rising chime for notifications and a
/// warm arpeggio for a match or a compliment. Respects the in-app switch, and
/// plays as "ambient" so the device's silent mode and other audio win.
enum OlfaSound { message, notification, match }

class SoundService {
  SoundService();
  final _players = <OlfaSound, AudioPlayer>{};
  bool enabled = true;

  Future<void> play(OlfaSound s) async {
    if (!enabled) return;
    try {
      final p = _players.putIfAbsent(s, AudioPlayer.new);
      if (p.audioSource == null) await p.setAsset('assets/sounds/${s.name}.wav');
      await p.seek(Duration.zero);
      await p.setVolume(s == OlfaSound.message ? 0.6 : 0.8);
      await p.play();
      if (s != OlfaSound.message) await HapticFeedback.lightImpact();
    } catch (_) {
      // sound is a nicety; never fail a user action because of it
    }
  }

  void dispose() {
    for (final p in _players.values) {
      p.dispose();
    }
  }
}

final soundServiceProvider = Provider<SoundService>((ref) {
  final s = SoundService();
  ref.onDispose(s.dispose);
  return s;
});

/// In-app sounds on/off (Settings › Notifications), remembered on the device.
class SoundsEnabled extends Notifier<bool> {
  static const _key = 'olfa.sounds';
  static const _store = FlutterSecureStorage();

  @override
  bool build() {
    _store.read(key: _key).then((v) {
      if (v == 'off') state = false;
    }).catchError((_) {});
    return true;
  }

  void set(bool on) {
    state = on;
    ref.read(soundServiceProvider).enabled = on;
    _store.write(key: _key, value: on ? 'on' : 'off').catchError((_) {});
  }
}

final soundsEnabledProvider = NotifierProvider<SoundsEnabled, bool>(SoundsEnabled.new);
